package im.autonova.mobile.data

import android.os.Build
import android.util.Base64
import android.content.Context
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.collect
import kotlinx.coroutines.launch
import java.io.File

/** Keeps protected backend access, encrypted configuration, and Room cache updates out of Compose UI. */
class AgentRepository(private val context: Context, private val cache: AgentCacheDao, private val config: SecureConfig) {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private val deviceAuditSynchronizer = DeviceAuditSynchronizer(cache)
    private val localModel = LocalModelEngine(context, config)
    private val localKnowledge = LocalKnowledgeEngine(cache)
    private val _messages = MutableStateFlow<List<ChatMessage>>(emptyList()); private val _tasks = MutableStateFlow<List<AgentTask>>(emptyList()); private val _projects = MutableStateFlow<List<AgentProject>>(emptyList())
    private val _memories = MutableStateFlow<List<MemoryItem>>(emptyList()); private val _activity = MutableStateFlow<List<ActivityItem>>(emptyList())
    private val _files = MutableStateFlow<List<FileItem>>(emptyList()); private val _tools = MutableStateFlow(listOf(ToolItem("local.workspace", "ASK"), ToolItem("browser.handoff", "ASK"), ToolItem("device.context", "ASK"))); private val _provider = MutableStateFlow<ProviderItem?>(null)
    private val _usage = MutableStateFlow<UsageSummary?>(null); private val _github = MutableStateFlow<GitHubSummary?>(null); private val _generatedImageUrl = MutableStateFlow<String?>(null)
    private val _research = MutableStateFlow<List<ResearchSession>>(emptyList()); private val _learningCandidates = MutableStateFlow<List<LearningCandidate>>(emptyList()); private val _capabilityGrants = MutableStateFlow<List<CapabilityGrant>>(emptyList()); private val _githubConnection = MutableStateFlow<GitHubConnection?>(null); private val _githubOperations = MutableStateFlow<List<GitHubOperation>>(emptyList()); private val _improvements = MutableStateFlow<List<ImprovementRecord>>(emptyList()); private val _taskEvidence = MutableStateFlow<List<TaskEvidence>>(emptyList()); private val _modelCapabilities = MutableStateFlow<List<ModelCapability>>(emptyList()); private val _localKnowledgeUsage = MutableStateFlow(LocalKnowledgeUsage(0, 0, 0))
    val messages: StateFlow<List<ChatMessage>> = _messages.asStateFlow(); val tasks: StateFlow<List<AgentTask>> = _tasks.asStateFlow(); val projects: StateFlow<List<AgentProject>> = _projects.asStateFlow(); val memories: StateFlow<List<MemoryItem>> = _memories.asStateFlow(); val activity: StateFlow<List<ActivityItem>> = _activity.asStateFlow(); val files: StateFlow<List<FileItem>> = _files.asStateFlow(); val tools: StateFlow<List<ToolItem>> = _tools.asStateFlow(); val provider: StateFlow<ProviderItem?> = _provider.asStateFlow(); val usage: StateFlow<UsageSummary?> = _usage.asStateFlow(); val github: StateFlow<GitHubSummary?> = _github.asStateFlow(); val generatedImageUrl: StateFlow<String?> = _generatedImageUrl.asStateFlow(); val research: StateFlow<List<ResearchSession>> = _research.asStateFlow(); val learningCandidates: StateFlow<List<LearningCandidate>> = _learningCandidates.asStateFlow(); val capabilityGrants: StateFlow<List<CapabilityGrant>> = _capabilityGrants.asStateFlow(); val githubConnection: StateFlow<GitHubConnection?> = _githubConnection.asStateFlow(); val githubOperations: StateFlow<List<GitHubOperation>> = _githubOperations.asStateFlow(); val improvements: StateFlow<List<ImprovementRecord>> = _improvements.asStateFlow(); val taskEvidence: StateFlow<List<TaskEvidence>> = _taskEvidence.asStateFlow(); val modelCapabilities: StateFlow<List<ModelCapability>> = _modelCapabilities.asStateFlow(); val localKnowledgeUsage: StateFlow<LocalKnowledgeUsage> = _localKnowledgeUsage.asStateFlow()
    private suspend fun refreshLocalKnowledgeUsage() { _localKnowledgeUsage.value = cache.localKnowledgeUsage() }
    private fun localDeviceContextDirectory(): File = File(context.filesDir, "device-context").also { it.mkdirs() }
    private fun refreshLocalDeviceContextFiles() { _files.value = localDeviceContextDirectory().listFiles()?.filter(File::isFile)?.sortedByDescending(File::lastModified)?.map { file -> FileItem("local-device-${file.name}", file.name, "application/octet-stream", file.length().coerceAtMost(Int.MAX_VALUE.toLong()).toInt()) } ?: emptyList() }
    init { refreshLocalDeviceContextFiles(); scope.launch { refreshLocalKnowledgeUsage() }; scope.launch { cache.observeTasks().collect { cached -> _tasks.value = cached.map { AgentTask(it.id, it.request, TaskStatus.valueOf(it.status), it.updatedAt) } } }; scope.launch { cache.observeMessages().collect { cached -> _messages.value = cached.map { ChatMessage(it.id, it.role, it.content, it.createdAt) } } }; scope.launch { cache.observeProjects().collect { cached -> _projects.value = cached.map { AgentProject(it.id, it.name, it.description) } } }; scope.launch { cache.observeMemories().collect { cached -> _memories.value = cached.map { MemoryItem(it.id, it.title, it.content, it.layer) } } }; scope.launch { cache.observeActivity().collect { cached -> _activity.value = cached.map { ActivityItem(it.id, it.title, it.detail, it.eventType) } } }; scope.launch { cache.observeResearch().collect { cached -> _research.value = cached.map { ResearchSession(it.id, it.query, it.status, it.summary) } } }; scope.launch { cache.observeLearningCandidates().collect { cached -> _learningCandidates.value = cached.map { LearningCandidate(it.id, it.title, it.content, it.layer, it.source, it.status) } } }; scope.launch { cache.observeCapabilityGrants().collect { cached -> _capabilityGrants.value = cached.map { CapabilityGrant(it.id, it.capability, it.scope, it.rationale, it.status, it.expiresAt.ifBlank { null }, it.outcome) } } } }
    fun createLocalTask(request: String) { val now = System.currentTimeMillis(); scope.launch { cache.upsertTasks(listOf(CachedTask("local-$now", request, TaskStatus.PLANNING.name, now))) } }
    suspend fun appendLocalMessage(message: ChatMessage) { cache.upsertMessage(CachedMessage(message.id, message.role, message.content, message.createdAt)) }
    fun recordLocalActivity(eventType: String, title: String, detail: String) { val now = System.currentTimeMillis(); scope.launch { cache.upsertActivity(listOf(CachedActivity("local-audit-$now", title, detail, eventType))) } }
    suspend fun recordDeviceCapability(capability: String, scopeValue: String, detail: String, outcome: String): Boolean = runCatching {
        val remoteAudit = api()?.let { client -> DeviceAuditRemote { event -> client.recordDeviceAudit(event.capability, event.scope, event.detail, event.outcome) } }
        if (!deviceAuditSynchronizer.record(DeviceAuditEvent(capability, scopeValue, detail, outcome), remoteAudit)) return false
        refresh(); true
    }.getOrDefault(false)
    private fun api(): MobileAgentApi? = if (config.remoteAgentEnabled()) config.accessToken()?.let { token -> config.apiBaseUrl()?.let { endpoint -> MobileAgentApi(endpoint, token) } } else null
    suspend fun refresh(): Boolean {
        val api = api() ?: return false
        val previousStatuses = _tasks.value.associate { it.id to it.status.name }
        api.registerDevice(DeviceRegistration(config.deviceId(), "Android ${Build.MODEL}", false))
        val snapshot = api.bootstrap()
        cache.upsertProjects(snapshot.projects.map { CachedProject(it.id.toString(), it.name, it.description ?: "") }); cache.upsertTasks(snapshot.tasks.map { CachedTask(it.id.toString(), it.request, it.status, System.currentTimeMillis()) }); cache.upsertMemories(snapshot.memories.map { CachedMemory(it.id.toString(), it.title, it.content, it.layer) }); cache.upsertActivity(snapshot.activity.map { CachedActivity(it.id.toString(), it.title, it.detail ?: "", it.eventType) })
        cache.upsertResearch(snapshot.research.map { CachedResearch(it.id.toString(), it.query, it.status, it.summary ?: "") }); cache.upsertLearningCandidates(snapshot.learningCandidates.map { CachedLearningCandidate(it.id.toString(), it.title, it.content, it.layer, it.source, it.status) }); cache.upsertCapabilityGrants(snapshot.capabilityGrants.map { CachedCapabilityGrant(it.id.toString(), it.capability, it.scope, it.rationale ?: "", it.status, it.expiresAt ?: "", it.outcome ?: "") })
        _files.value = snapshot.files.map { FileItem(it.id.toString(), it.name, it.mimeType, it.sizeBytes) }; _tools.value = snapshot.toolPermissions.map { ToolItem(it.toolKey, it.policy) }; _provider.value = snapshot.provider?.let { ProviderItem(it.name, it.providerType, it.activeModel, it.costMode, it.hasApiKey) }
        _githubConnection.value = snapshot.githubConnection?.let { GitHubConnection(it.login, it.scopes) }; _githubOperations.value = snapshot.githubOperations.map { GitHubOperation(it.id.toString(), it.repository, it.operation, it.status, it.resultSummary ?: "", it.errorSummary ?: "") }; _improvements.value = snapshot.improvements.map { ImprovementRecord(it.id.toString(), it.scope, it.title, it.proposedChange, it.evidence, it.testOutcome ?: "", it.benchmarkSummary ?: "", it.versionLabel, it.status, it.reviewNote ?: "") }; _taskEvidence.value = snapshot.taskEvidence.map { TaskEvidence(it.id.toString(), it.taskId.toString(), it.kind, it.toolKey ?: "", it.summary, it.evidence ?: "", it.outcome) }; _modelCapabilities.value = snapshot.modelCapabilities.map { ModelCapability(it.modality, it.route, it.availability, it.note) }
        if (config.notificationsEnabled()) snapshot.tasks.filter { it.status in listOf("COMPLETED", "FAILED") && previousStatuses[it.id.toString()] != it.status }.forEach { AgentNotifier(context).notifyTask(it.id.toString(), it.request, it.status) }
        return true
    }
    suspend fun submit(text: String, forceRemote: Boolean = false): Boolean {
        val now = System.currentTimeMillis(); appendLocalMessage(ChatMessage("local-$now", "user", text, now)); val api = if (forceRemote || config.remoteAgentEnabled()) api() else null
        if (api != null) { val assistantId = "agent-${System.currentTimeMillis()}"; val assistantCreatedAt = System.currentTimeMillis(); var receivedSnapshot = false; val result = runCatching { api.sendMessage(text) { snapshot -> if (snapshot.isNotBlank()) { receivedSnapshot = true; cache.upsertMessage(CachedMessage(assistantId, "assistant", snapshot, assistantCreatedAt)) } } }; if (result.isFailure) { appendLocalMessage(ChatMessage("agent-error-${System.currentTimeMillis()}", "assistant", "Your request was saved locally, but the optional remote agent could not reply. Retry after checking the endpoint and network, or switch to Local Only mode and import a local model.", System.currentTimeMillis())); recordLocalActivity("MODEL_ROUTE", "Optional remote agent unavailable", result.exceptionOrNull()?.message ?: "The remote request failed."); return false }; val reply = result.getOrNull(); if (!receivedSnapshot && !reply.isNullOrBlank()) cache.upsertMessage(CachedMessage(assistantId, "assistant", reply, assistantCreatedAt)); recordLocalActivity("MODEL_ROUTE", "Optional remote model selected", "The selected remote agent returned a response for the user request.") }
        else {
            val memory = cache.localMemorySnippets().joinToString("\n") { "- ${it.title}: ${it.content.take(500)}" }
            val knowledge = localKnowledge.retrieve(text).joinToString("\n\n") { "[Local document: ${it.title}; lexical relevance ${it.score}]\n${it.excerpt}" }
            val prompt = buildString { append("You are Autonova running fully on this Android device. Be concise, honest about limitations, and do not claim network access or actions you did not perform."); if (memory.isNotBlank()) append("\n\nApproved local memory:\n$memory"); if (knowledge.isNotBlank()) append("\n\nLocal document evidence:\n$knowledge"); append("\n\nUser request:\n$text") }
            val response = localModel.generate(prompt).getOrElse { OfflineQuickAssistant.respond(text, memory, knowledge) }
            appendLocalMessage(ChatMessage("local-model-${System.currentTimeMillis()}", "assistant", response, System.currentTimeMillis()))
            recordLocalActivity("MODEL_ROUTE", "Local response recorded", if (localModel.isAvailable()) "Generated with the user-selected local model, local memory, and local document evidence." else "Generated an on-device quick plan because no compatible local model is installed.")
        }
        if (text.lowercase().startsWith("build") || text.lowercase().startsWith("create") || text.lowercase().startsWith("research") || text.lowercase().startsWith("plan")) createLocalTask(text)
        return true
    }
    suspend fun createProject(name: String, description: String): Boolean = runCatching { val client = api(); if (client != null) { client.createProject(name, description); refresh() } else { cache.upsertProjects(listOf(CachedProject("local-project-${System.currentTimeMillis()}", name, description))); recordLocalActivity("LOCAL_PROJECT", "Local workspace created", name) }; true }.getOrDefault(false)
    suspend fun createTask(request: String): Boolean = runCatching { val client = api(); if (client != null) { client.createTask(request); refresh() } else { val now = System.currentTimeMillis(); cache.upsertTasks(listOf(CachedTask("local-task-$now", request, TaskStatus.PLANNING.name, now))); recordLocalActivity("LOCAL_TASK", "Local task started", request.take(240)) }; true }.getOrDefault(false)
    private suspend fun updateLocalTask(id: String, status: TaskStatus, event: String, detail: String): Boolean = runCatching { val current = cache.localTask(id) ?: error("Local task was not found."); cache.upsertTasks(listOf(current.copy(status = status.name, updatedAt = System.currentTimeMillis()))); recordLocalActivity("LOCAL_TASK", event, detail); true }.getOrDefault(false)
    suspend fun changeTaskStatus(id: String, status: String): Boolean = runCatching { val client = api(); if (client != null) { client.changeTaskStatus(id, status); refresh(); true } else updateLocalTask(id, TaskStatus.valueOf(status), "Local task status changed", "The task moved to ${status.lowercase().replace('_', ' ')} on this device.") }.getOrDefault(false)
    suspend fun createMemory(title: String, content: String, layer: String): Boolean = runCatching { val client = api(); if (client != null) { client.createMemory(title, content, layer); refresh() } else { cache.upsertMemories(listOf(CachedMemory("local-memory-${System.currentTimeMillis()}", title, content, layer))); recordLocalActivity("LOCAL_MEMORY", "Local memory saved", title) }; true }.getOrDefault(false)
    suspend fun updateMemory(id: String, title: String, content: String, layer: String): Boolean = runCatching { val client = api(); if (client != null) { client.updateMemory(id, title, content, layer); refresh() } else { val existing = cache.localMemory(id) ?: error("Local memory was not found."); cache.upsertMemories(listOf(existing.copy(title = title, content = content, layer = layer))); recordLocalActivity("LOCAL_MEMORY", "Local memory updated", title) }; true }.getOrDefault(false)
    suspend fun deleteMemory(id: String): Boolean = runCatching { val client = api(); if (client != null) { client.deleteMemory(id); refresh() } else { cache.deleteLocalMemory(id); recordLocalActivity("LOCAL_MEMORY", "Local memory deleted", id) }; true }.getOrDefault(false)
    suspend fun setToolPolicy(key: String, policy: String): Boolean = runCatching { val client = api(); if (client != null) { client.setToolPolicy(key, policy); refresh() } else { _tools.value = _tools.value.map { if (it.key == key) it.copy(policy = policy) else it }; recordLocalActivity("LOCAL_TOOL_POLICY", "Local tool policy updated", "$key is now $policy.") }; true }.getOrDefault(false)
    suspend fun uploadFile(document: LocalDocument, bytes: ByteArray): Boolean = runCatching { require(bytes.size <= 10 * 1024 * 1024) { "Files must be 10 MB or smaller." }; api()?.uploadFile(document.name, document.mimeType, Base64.encodeToString(bytes, Base64.NO_WRAP)) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun indexLocalDocument(document: LocalDocument, bytes: ByteArray): Boolean = runCatching { val readable = bytes.toString(Charsets.UTF_8); val chunks = localKnowledge.index(document.uri.toString(), document.name, readable).getOrThrow(); refreshLocalKnowledgeUsage(); recordLocalActivity("LOCAL_KNOWLEDGE", "Document indexed locally", "${document.name}: $chunks local text chunks. No network transfer occurred."); true }.getOrDefault(false)
    suspend fun clearLocalKnowledgeIndex(): Boolean = runCatching { cache.clearKnowledgeChunks(); refreshLocalKnowledgeUsage(); recordLocalActivity("LOCAL_KNOWLEDGE", "Local document index cleared", "The user cleared offline retrieval chunks. Source documents remain in their selected folder and no network transfer occurred."); true }.getOrDefault(false)
    suspend fun clearLocalActivityCache(): Boolean = runCatching { cache.clearActivity(); recordLocalActivity("LOCAL_CACHE", "Local activity cache cleared", "The user cleared cached activity summaries. Tasks, memories, documents, and source files were not deleted."); true }.getOrDefault(false)
    suspend fun uploadDeviceContext(name: String, mimeType: String, bytes: ByteArray): Boolean = runCatching { require(bytes.size in 1..10 * 1024 * 1024) { "Device context must be 10 MB or smaller." }; val client = api(); if (client != null) { client.uploadFile(name, mimeType, Base64.encodeToString(bytes, Base64.NO_WRAP)); refresh() } else { val safeName = name.replace(Regex("[^A-Za-z0-9._-]"), "_"); File(localDeviceContextDirectory(), "${System.currentTimeMillis()}-$safeName").writeBytes(bytes); refreshLocalDeviceContextFiles(); recordLocalActivity("LOCAL_DEVICE_CONTEXT", "Device context saved locally", "$name was saved in private app storage; it was not uploaded.") }; true }.getOrDefault(false)
    suspend fun saveProvider(name: String, providerType: String, baseUrl: String, model: String, apiKey: String, costMode: String): Boolean = runCatching { api()?.saveProvider(ProviderRequest(name, providerType, baseUrl.ifBlank { null }, model.ifBlank { null }, apiKey.ifBlank { null }, costMode)) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun refreshUsage(): Boolean = runCatching { val client = api(); if (client != null) { val wire = client.usage(); _usage.value = UsageSummary(wire.totals.inputTokens, wire.totals.outputTokens, wire.totals.toolCalls, wire.totals.estimatedCostMicros, wire.records.map { UsageRecord(it.model, it.inputTokens, it.outputTokens, it.toolCalls) }) } else _usage.value = UsageSummary(0, 0, 0, 0, listOf(UsageRecord("Local Only", 0, 0, 0))); true }.getOrDefault(false)
    suspend fun generateImage(prompt: String): Boolean = runCatching { _generatedImageUrl.value = (api()?.generateImage(prompt) ?: error("Connect the secure session first.")).url; refresh() }.isSuccess
    suspend fun inspectGitHub(repository: String): Boolean = runCatching { val wire = api()?.inspectGitHub(repository) ?: error("Connect the secure session first."); _github.value = GitHubSummary(wire.repo.fullName, wire.repo.description ?: "No description.", wire.repo.defaultBranch, wire.repo.stars, wire.branches.map { it.name }, wire.issues.map { "#${it.number} ${it.title}" }, wire.pulls.map { "#${it.number} ${it.title}" }, wire.commits.map { "${it.sha.take(7)} ${it.commit.message.lineSequence().firstOrNull().orEmpty()}" }) }.isSuccess
    suspend fun research(query: String, sources: List<String>): Boolean = runCatching { val client = api(); if (client != null) { client.research(query, sources); refresh() } else { cache.upsertResearch(listOf(CachedResearch("local-research-${System.currentTimeMillis()}", query, "LOCAL_BROWSER_HANDOFF", "Saved a local research brief for ${sources.size} selected public source${if (sources.size == 1) "" else "s"}. Open the sources visibly in your browser; install a local model or connect the optional agent to synthesize them."))); recordLocalActivity("LOCAL_RESEARCH", "Local research brief saved", query.take(240)) }; true }.getOrDefault(false)
    suspend fun createLearningCandidate(title: String, content: String, layer: String, source: String = "ANDROID_LOCAL"): Boolean = runCatching { val client = api(); if (client != null) { client.createLearningCandidate(LearningCandidateRequest(title, content, layer, source)); refresh() } else { cache.upsertLearningCandidates(listOf(CachedLearningCandidate("local-learning-${System.currentTimeMillis()}", title, content, layer, source, "PENDING"))); recordLocalActivity("LOCAL_LEARNING", "Local learning candidate saved", title) }; true }.getOrDefault(false)
    suspend fun prepareLearningCandidates(): Boolean = runCatching {
        if (!config.learningReviewEnabled()) return@runCatching true
        val client = api() ?: return@runCatching true
        cache.recentMessages().asReversed().filter { it.role == "user" }.take(12).forEach { message ->
            val normalized = message.content.trim()
            val pattern = Regex("(?i)^(remember|i prefer|my preference is|always|never)\\b")
            if (normalized.length in 8..1200 && pattern.containsMatchIn(normalized)) {
                val fingerprint = "${message.id}:${normalized.hashCode()}"
                if (!config.hasLearningFingerprint(fingerprint)) { client.createLearningCandidate(LearningCandidateRequest("Review suggested preference", normalized, "PERSONAL", "ANDROID_BACKGROUND_REVIEW")); config.markLearningFingerprint(fingerprint) }
            }
        }
        refresh(); true
    }.getOrDefault(false)
    suspend fun reviewLearningCandidate(id: String, status: String, title: String? = null, content: String? = null, layer: String? = null): Boolean = runCatching { val client = api(); if (client != null) { client.reviewLearningCandidate(id, LearningDecisionRequest(status, title, content, layer)); refresh() } else { val candidate = cache.localLearningCandidate(id) ?: error("Local learning candidate was not found."); val nextTitle = title ?: candidate.title; val nextContent = content ?: candidate.content; val nextLayer = layer ?: candidate.layer; cache.upsertLearningCandidates(listOf(candidate.copy(title = nextTitle, content = nextContent, layer = nextLayer, status = status))); if (status == "APPROVED") cache.upsertMemories(listOf(CachedMemory("learned-$id", nextTitle, nextContent, nextLayer))); recordLocalActivity("LOCAL_LEARNING", "Local learning candidate $status", nextTitle) }; true }.getOrDefault(false)
    suspend fun createImprovement(scopeValue: String, title: String, proposedChange: String, evidence: String, testOutcome: String, benchmarkSummary: String, versionLabel: String): Boolean = runCatching { api()?.createImprovement(ImprovementRequest(scopeValue, title, proposedChange, evidence, testOutcome, benchmarkSummary, versionLabel)) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun reviewImprovement(id: String, status: String, note: String): Boolean = runCatching { api()?.reviewImprovement(id, ImprovementDecisionRequest(status, note)) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun observeTask(id: String, summary: String, evidence: String): Boolean = runCatching { val client = api(); if (client != null) { client.observeTask(id, TaskObservationRequest(summary, evidence.ifBlank { null })); refresh(); true } else updateLocalTask(id, TaskStatus.RUNNING, "Local observation recorded", summary.ifBlank { "Owner recorded a local task observation." }) }.getOrDefault(false)
    suspend fun selectTaskTool(id: String, toolKey: String, rationale: String): Boolean = runCatching { val client = api(); if (client != null) { client.selectTaskTool(id, TaskToolRequest(toolKey, rationale)); refresh(); true } else updateLocalTask(id, TaskStatus.WAITING_FOR_USER, "Local task step selected", "$toolKey: $rationale") }.getOrDefault(false)
    suspend fun approveTaskTool(id: String, toolKey: String, approved: Boolean, note: String): Boolean = runCatching { val client = api(); if (client != null) { client.approveTaskTool(id, TaskToolApprovalRequest(toolKey, approved, note.ifBlank { null })); refresh(); true } else updateLocalTask(id, if (approved) TaskStatus.VERIFYING else TaskStatus.PLANNING, "Local task step ${if (approved) "approved" else "declined"}", "$toolKey: ${note.ifBlank { "Owner decision recorded locally." }}") }.getOrDefault(false)
    suspend fun repairTask(id: String, diagnosis: String): Boolean = runCatching { val client = api(); if (client != null) { client.repairTask(id, TaskRepairRequest(diagnosis, listOf(TaskRepairStepRequest("Apply the approved repair", diagnosis)))); refresh(); true } else updateLocalTask(id, TaskStatus.RUNNING, "Local task repair started", diagnosis) }.getOrDefault(false)
    suspend fun escalateTask(id: String, level: String, summary: String): Boolean = runCatching { val client = api(); if (client != null) { client.escalateTask(id, TaskEscalationRequest(level, summary)); refresh(); true } else updateLocalTask(id, TaskStatus.FAILED, "Local task escalated", "$level: $summary") }.getOrDefault(false)
    suspend fun verifyTask(id: String, passed: Boolean, evidence: String): Boolean = runCatching { val client = api(); if (client != null) { client.verifyTask(id, TaskVerificationRequest(passed, evidence)); refresh(); true } else updateLocalTask(id, if (passed) TaskStatus.COMPLETED else TaskStatus.FAILED, "Local task verified", evidence) }.getOrDefault(false)
    suspend fun createCapabilityGrant(capability: String, scopeValue: String, rationale: String, expiresAt: String? = null): Boolean = runCatching { val client = api(); if (client != null) { client.createCapabilityGrant(CapabilityGrantRequest(capability, scopeValue, rationale.ifBlank { null }, expiresAt)); refresh() } else { cache.upsertCapabilityGrants(listOf(CachedCapabilityGrant("local-grant-${System.currentTimeMillis()}", capability, scopeValue, rationale, "PENDING", expiresAt.orEmpty(), "Awaiting your local review."))); recordLocalActivity("LOCAL_CAPABILITY", "Local capability grant proposed", "$capability: $scopeValue") }; true }.getOrDefault(false)
    suspend fun updateCapabilityGrant(id: String, status: String): Boolean = runCatching { val client = api(); if (client != null) { client.updateCapabilityGrant(id, status); refresh() } else { val grant = cache.localCapabilityGrant(id) ?: error("Local capability grant was not found."); cache.upsertCapabilityGrants(listOf(grant.copy(status = status, outcome = "Updated locally by the owner."))); recordLocalActivity("LOCAL_CAPABILITY", "Local capability grant $status", grant.capability) }; true }.getOrDefault(false)
    suspend fun connectGitHub(token: String, scopes: String): Boolean = runCatching { api()?.connectGitHub(token, scopes) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun disconnectGitHub(): Boolean = runCatching { api()?.disconnectGitHub() ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun proposeGitHubOperation(repository: String, operation: String, title: String, body: String, branch: String, fromBranch: String, head: String, base: String): Boolean = runCatching { api()?.proposeGitHubOperation(GitHubOperationRequest(repository, operation, title.ifBlank { null }, body.ifBlank { null }, branch.ifBlank { null }, fromBranch.ifBlank { null }, head.ifBlank { null }, base.ifBlank { null })) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun proposeWorkspaceFileSync(repository: String, commitMessage: String, branch: String, filePath: String, content: String): Boolean = runCatching { api()?.proposeGitHubOperation(GitHubOperationRequest(repository = repository, operation = "WRITE_WORKSPACE_FILE", title = commitMessage, branch = branch.ifBlank { null }, filePath = filePath, content = content)) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun approveGitHubOperation(id: String): Boolean = runCatching { api()?.approveGitHubOperation(id) ?: error("Connect the secure session first."); refresh() }.isSuccess
    suspend fun cancelGitHubOperation(id: String): Boolean = runCatching { api()?.cancelGitHubOperation(id) ?: error("Connect the secure session first."); refresh() }.isSuccess
}

data class MemoryItem(val id: String, val title: String, val content: String, val layer: String)
data class ActivityItem(val id: String, val title: String, val detail: String, val eventType: String)
data class FileItem(val id: String, val name: String, val mimeType: String, val sizeBytes: Int)
data class ToolItem(val key: String, val policy: String)
data class ProviderItem(val name: String, val type: String, val model: String?, val costMode: String, val hasApiKey: Boolean)
data class UsageRecord(val model: String, val inputTokens: Int, val outputTokens: Int, val toolCalls: Int)
data class UsageSummary(val inputTokens: Int, val outputTokens: Int, val toolCalls: Int, val estimatedCostMicros: Int, val records: List<UsageRecord>)
data class GitHubSummary(val name: String, val description: String, val branch: String, val stars: Int, val branches: List<String>, val issues: List<String>, val pulls: List<String>, val commits: List<String>)
